/**
 * Visual thumbnail of a file (image or video frame generated by main), with the
 * adult blur overlay. Purely presentational: the parent places its own "open"
 * button as a sibling (see `MediaTileButton`).
 */
import { useState } from 'react';
import { File, Film, Image as ImageIcon, Music2, Play } from 'lucide-react';
import type { MediaType } from '../../../shared/domain/media.ts';
import { ADULT_BLUR_MEDIA_CLASS } from '../../shared/lib/adult-content.ts';
import { thumbnailKind, type ThumbnailSize } from '../../shared/lib/media-cache.ts';
import { Spinner } from '../../shared/ui/spinner.tsx';
import { AdultBlurScrim } from './AdultBlurScrim.tsx';
import type { AdultBlur } from './useAdultBlur.ts';
import { useMediaUrl } from './useMediaUrl.ts';

const ICONS: Record<MediaType, typeof File> = {
  image: ImageIcon,
  video: Film,
  audio: Music2,
  document: File,
  other: File
};

export interface MediaThumbnailProps {
  readonly path: string;
  readonly mediaType: MediaType;
  readonly blur: AdultBlur;
  /** Bigger placeholder icon (large tiles). */
  readonly large?: boolean;
  /** Rendition requested from main: `large` for tiles wider than the small thumbnail. */
  readonly size?: ThumbnailSize;
  /** Round play badge over videos (library style). */
  readonly playBadge?: boolean;
  readonly compactScrim?: boolean;
}

export function MediaThumbnail({
  path,
  mediaType,
  blur,
  large = false,
  size = 'small',
  playBadge = false,
  compactScrim = false
}: MediaThumbnailProps) {
  const visual = mediaType === 'image' || mediaType === 'video';
  const thumb = useMediaUrl(thumbnailKind(size), path, visual);
  // A URL that still failed after one refetch: show the placeholder icon instead of a broken image.
  const [brokenUrl, setBrokenUrl] = useState<string | null>(null);
  const url = thumb.status === 'ready' && thumb.media.url !== brokenUrl ? thumb.media.url : null;
  const Icon = ICONS[mediaType];

  return (
    <div className="absolute inset-0 overflow-hidden bg-bg/40">
      {url !== null ? (
        <img
          src={url}
          alt=""
          draggable={false}
          decoding="async"
          onError={() => thumb.reportLoadError(url, () => setBrokenUrl(url))}
          className={`absolute inset-0 h-full w-full object-cover ${blur.blurred ? ADULT_BLUR_MEDIA_CLASS : ''}`}
        />
      ) : thumb.status === 'loading' ? (
        <span className="absolute inset-0 grid place-items-center text-text-4">
          <Spinner className="h-5 w-5" />
        </span>
      ) : (
        <span className="absolute inset-0 grid place-items-center text-text-4">
          <Icon className={large ? 'h-7 w-7' : 'h-5 w-5'} strokeWidth={1.6} aria-hidden />
        </span>
      )}
      {mediaType === 'video' && playBadge && !blur.blurred ? (
        <span className="pointer-events-none absolute inset-0 grid place-items-center bg-bg/20">
          <span className="inline-flex h-10 w-10 items-center justify-center rounded-full border border-border/80 bg-bg/85 text-text shadow-float">
            <Play className="h-5 w-5 translate-x-px" strokeWidth={2} aria-hidden />
          </span>
        </span>
      ) : null}
      {blur.blurred ? <AdultBlurScrim onReveal={blur.reveal} compact={compactScrim} /> : null}
    </div>
  );
}
